import { fmtSet, ruleText, type LLAnalysis } from './grammar'
import { precTable, type Prec } from './precedence'

export interface TableCell {
  text: string
  /** Tooltip / explanation of the cell. */
  title: string
  /** More than one entry in the cell (LL conflict). */
  conflict: boolean
}

export interface TableModel {
  title: string
  /** Column labels; header[0] labels the row-header column. */
  header: string[]
  /** Each row: its header (first column) and one cell per remaining column. */
  rows: { head: string; cells: TableCell[] }[]
}

const plain = (text: string): TableCell => ({ text, title: '', conflict: false })

/** The table as text: the header row, then each row with its header first. */
export const tableGrid = (m: TableModel): string[][] => [m.header, ...m.rows.map((r) => [r.head, ...r.cells.map((c) => c.text)])]

/** LL table: row = nonterminal, column = terminal ($ last), cell = rule numbers. */
export function llTableModel(a: LLAnalysis): TableModel {
  return {
    title: 'LL tabuľka',
    header: ['', ...a.cols],
    rows: a.N.map((A) => ({
      head: A,
      cells: a.cols.map((c) => {
        const cell = a.table.get(A)!.get(c) ?? []
        return {
          text: cell.join(', '),
          title: cell.map((i) => `${i}: ${ruleText(a.rules[i - 1])}`).join('\n'),
          conflict: cell.length > 1,
        }
      }),
    })),
  }
}

/** Empty, First and Follow of each nonterminal. */
export function llSetsTableModel(a: LLAnalysis): TableModel {
  return {
    title: 'Množiny Empty, First, Follow',
    header: ['Neterminál', 'Empty', 'First', 'Follow'],
    rows: a.N.map((n) => ({
      head: n,
      cells: [a.empty.has(n) ? '{ ε }' : '∅', fmtSet(a.order(a.first.get(n)!)), fmtSet(a.order(a.follow.get(n)!))].map(plain),
    })),
  }
}

/** Predict set of each (numbered) rule. */
export function llPredictTableModel(a: LLAnalysis): TableModel {
  return {
    title: 'Predict',
    header: ['#', 'Pravidlo', 'Predict'],
    rows: a.rules.map((r, i) => ({ head: String(i + 1), cells: [ruleText(r), fmtSet(a.order(a.predict[i]))].map(plain) })),
  }
}

/** Precedence table: row = terminal on the stack, column = input token, both with $ last. */
export function precTableModel(prec: Prec): TableModel {
  const t = precTable(prec)
  return {
    title: 'Precedenčná tabuľka',
    header: ['', ...t.columns],
    rows: t.rows.map(({ terminal, relations }) => ({
      head: terminal,
      cells: relations.map((rel, i) => ({
        text: rel,
        title: `Tabuľka[${terminal}, ${t.columns[i]}] = ${rel || 'prázdne (chyba)'}`,
        conflict: false,
      })),
    })),
  }
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Selection and detail-line helpers of the table model (moved here from components/llGrid.ts, which only
//          worked on TableModel and clashed by case with LLGrid.tsx).

/** The model restricted to the given row heads and column labels (model order is kept). */
export function pickTableModel(m: TableModel, rows: string[], cols: string[]): TableModel {
  const keepRows = new Set(rows)
  const keepCols = new Set(cols)
  const colIdx = m.header.slice(1).flatMap((c, i) => (keepCols.has(c) ? [i] : []))
  return {
    title: m.title,
    header: [m.header[0], ...colIdx.map((i) => m.header[i + 1])],
    rows: m.rows.filter((r) => keepRows.has(r.head)).map((r) => ({ head: r.head, cells: colIdx.map((i) => r.cells[i]) })),
  }
}

/** One-line description of a cell: `[row, column] → rules`, a conflict or an empty (error) cell. */
export function cellDetail(m: TableModel, row: number, col: number): string {
  const r = m.rows[row]
  const c = r?.cells[col]
  if (!r || !c) return ''
  const where = `[${r.head}, ${m.header[col + 1]}] → `
  if (!c.text) return `${where}prázdna bunka (syntaktická chyba)`
  const rules = (c.title || c.text).split('\n').join('; ')
  return where + (c.conflict ? `konflikt: ${rules}` : rules)
}
